INSERT Sys_OperationLog(Id,UserId,UserName,Module,Action,TargetType,TargetId,Description,OldValue,NewValue,IP,CreateTime) VALUES(35,9,N'guoqiang',N'System',N'Login',N'Sys_User',9,N'User login',NULL,NULL,'192.168.1.100','2025-012-01 08:00');
