GO
-- ===== 10. Data Self-Check =====
PRINT '=== Self-check start ==='

IF EXISTS(SELECT po.OrderNo FROM Pur_PurchaseOrder po JOIN (SELECT PurchaseOrderId,SUM(Amount) s FROM Pur_PurchaseOrderDetail GROUP BY PurchaseOrderId) d ON po.Id=d.PurchaseOrderId WHERE ABS(po.TotalAmount-d.s)>0.01)
BEGIN RAISERROR('PO amount mismatch!',16,1);ROLLBACK;RETURN;END

IF EXISTS(SELECT pi.InNo FROM Pur_PurchaseIn pi JOIN (SELECT PurchaseInId,SUM(Amount) s FROM Pur_PurchaseInDetail GROUP BY PurchaseInId) d ON pi.Id=d.PurchaseInId WHERE ABS(pi.TotalAmount-d.s)>0.01)
BEGIN RAISERROR('PurchaseIn amount mismatch!',16,1);ROLLBACK;RETURN;END

IF EXISTS(SELECT so.OrderNo FROM Sale_SaleOrder so JOIN (SELECT SaleOrderId,SUM(Amount) s FROM Sale_SaleOrderDetail GROUP BY SaleOrderId) d ON so.Id=d.SaleOrderId WHERE ABS(so.TotalAmount-d.s)>0.01)
BEGIN RAISERROR('SO amount mismatch!',16,1);ROLLBACK;RETURN;END

IF EXISTS(SELECT so.OutNo FROM Sale_SaleOut so JOIN (SELECT SaleOutId,SUM(Amount) s FROM Sale_SaleOutDetail GROUP BY SaleOutId) d ON so.Id=d.SaleOutId WHERE ABS(so.TotalAmount-d.s)>0.01)
BEGIN RAISERROR('SaleOut amount mismatch!',16,1);ROLLBACK;RETURN;END

IF EXISTS(SELECT pr.ReturnNo FROM Pur_PurchaseReturn pr JOIN (SELECT PurchaseReturnId,SUM(Amount) s FROM Pur_PurchaseReturnDetail GROUP BY PurchaseReturnId) d ON pr.Id=d.PurchaseReturnId WHERE ABS(pr.TotalAmount-d.s)>0.01)
BEGIN RAISERROR('PurchaseReturn amount mismatch!',16,1);ROLLBACK;RETURN;END

IF EXISTS(SELECT sr.ReturnNo FROM Sale_Return sr JOIN (SELECT SaleReturnId,SUM(Amount) s FROM Sale_ReturnDetail GROUP BY SaleReturnId) d ON sr.Id=d.SaleReturnId WHERE ABS(sr.TotalAmount-d.s)>0.01)
BEGIN RAISERROR('SaleReturn amount mismatch!',16,1);ROLLBACK;RETURN;END

IF EXISTS(SELECT pod.Id FROM Pur_PurchaseOrderDetail pod LEFT JOIN Base_Product p ON pod.ProductId=p.Id WHERE p.Id IS NULL)
BEGIN RAISERROR('Invalid product ref in purchase detail!',16,1);ROLLBACK;RETURN;END
IF EXISTS(SELECT sod.Id FROM Sale_SaleOrderDetail sod LEFT JOIN Base_Product p ON sod.ProductId=p.Id WHERE p.Id IS NULL)
BEGIN RAISERROR('Invalid product ref in sale detail!',16,1);ROLLBACK;RETURN;END

IF EXISTS(SELECT u.Id FROM Sys_User u LEFT JOIN Sys_UserRole ur ON u.Id=ur.UserId WHERE ur.Id IS NULL)
BEGIN RAISERROR('User without role found!',16,1);ROLLBACK;RETURN;END

PRINT '=== Self-check passed ==='
COMMIT TRANSACTION;
PRINT '=== Demo data imported successfully ==='
END TRY
BEGIN CATCH
    PRINT '=== Error: ' + ERROR_MESSAGE() + ' ==='
    ROLLBACK TRANSACTION;
    THROW;
END CATCH
